BANK.update({
"phy_kinematics": [
{"qtype":"选择题","difficulty":1,"stem":"一物体做匀加速直线运动，初速度 v_0 = 2 m/s，加速度 a = 1 m/s^2，则第 3 s 末的速度为","options":["A. 3 m/s","B. 4 m/s","C. 5 m/s","D. 6 m/s"],"answer":"C","analysis":"由速度公式 v = v_0 + at = 2 + 1×3 = 5 m/s。注意「第3 s末」即 t=3 s，不是前3 s的位移。"},
{"qtype":"选择题","difficulty":1,"stem":"汽车以 10 m/s 的速度匀速行驶，刹车后做匀减速运动，加速度大小为 2 m/s^2，则刹车后 3 s 内的位移为","options":["A. 15 m","B. 16 m","C. 21 m","D. 75 m"],"answer":"C","analysis":"刹车问题必须先判断车是否已停。停车时间 t_0 = v_0/a = 5 s，3 s 时仍在运动。x = v_0 t - ½at^2 = 30 - 9 = 21 m。易错点是直接套用 3 s 而忽略停车时间，本题 3 s 内未停车故用此式。"},
{"qtype":"选择题","difficulty":2,"stem":"一物体由静止开始做匀加速直线运动，在第 1 s 内位移为 2 m，则前 3 s 内的位移为","options":["A. 6 m","B. 12 m","C. 18 m","D. 36 m"],"answer":"C","analysis":"由 x_1 = ½at^2 得 a = 2×2/1 = 4 m/s^2。前3 s 位移 x = ½×4×3^2 = 18 m。也可用初速度为零匀变速位移比 1:4:9，第1 s位移2 m，前3 s位移 = 2×9 = 18 m。"},
{"qtype":"选择题","difficulty":2,"stem":"做匀变速直线运动的物体，在第 2 s 内位移为 4 m，第 5 s 内位移为 10 m，则其加速度为","options":["A. 1 m/s^2","B. 2 m/s^2","C. 3 m/s^2","D. 4 m/s^2"],"answer":"B","analysis":"利用逐差思想：连续相等时间（1 s）内位移差 Δx = aT^2。第5 s与第2 s相隔3个间隔，故 x_5 - x_2 = 3aT^2，10-4 = 3a×1，得 a = 2 m/s^2。"},
{"qtype":"选择题","difficulty":2,"stem":"关于匀变速直线运动，下列说法正确的是","options":["A. 加速度的方向一定与速度方向相同","B. 加速度恒定不变（大小和方向都不变）","C. 相等时间内速度的变化量不相等","D. 物体的速度总是均匀增大"],"answer":"B","analysis":"匀变速直线运动的定义就是加速度恒定（大小、方向都不变）的直线运动，B正确。A错，匀减速运动中加速度方向与速度方向相反；C错，由 Δv = aΔt，加速度恒定时相等时间内速度变化量相等；D错，匀减速直线运动速度均匀减小。"},
{"qtype":"选择题","difficulty":3,"stem":"汽车以 20 m/s 行驶，前方 100 m 处有障碍物，司机反应时间 0.5 s 后刹车，刹车加速度大小 5 m/s^2，下列判断正确的是","options":["A. 汽车不会撞上","B. 汽车恰好停在障碍物处","C. 汽车会撞上","D. 无法判断"],"answer":"A","analysis":"反应距离 10 m，刹车距离 v^2/(2a)=400/10=40 m，总需 50 m，小于 100 m，故不会撞上。易错点：忘记加反应时间距离。"},
{"qtype":"选择题","difficulty":3,"stem":"一物体做自由落体运动（g 取 10 m/s^2），落地前最后 1 s 内下落了 25 m，则物体下落的总高度为","options":["A. 31.25 m","B. 45 m","C. 61.25 m","D. 80 m"],"answer":"B","analysis":"由最后1 s位移 ½g[t^2-(t-1)^2] = 10t-5 = 25 解得 t=3 s，总高度 H=½gt^2=45 m。易错点是把最后1 s位移当成 g×1^2。"},
{"qtype":"选择题","difficulty":3,"stem":"物体从斜面顶端由静止匀加速滑下，前半段位移与后半段位移所用时间之比为","options":["A. 1:1","B. 1:(√2-1)","C. 1:(√2+1)","D. √2:1"],"answer":"B","analysis":"初速度为零匀加速，位移与时间平方成正比。设总位移 2s 用时 t_总 = √(4s/a)，前半段 s 用时 t_1 = √(2s/a)。后半段用时 t_2 = t_总 - t_1。t_1:t_2 = √2 : (2-√2) = 1 : (√2-1)。"},
{"qtype":"填空题","difficulty":1,"stem":"子弹以 600 m/s 的速度射入固定木板，穿过 20 cm 后速度变为零，设子弹在木板中做匀减速直线运动，则其加速度大小为____ m/s^2。","options":[],"answer":"9×10^5","analysis":"由 v^2 = 2ax（末速度为零），a = v^2/(2x) = 600^2/(2×0.2) = 360000/0.4 = 9×10^5 m/s^2。注意位移单位换算成 m。"},
{"qtype":"填空题","difficulty":2,"stem":"某质点做匀变速直线运动，第 3 s 内位移为 6 m，第 6 s 内位移为 12 m，则其加速度 a = ____ m/s^2，初速度 v_0 = ____ m/s。","options":[],"answer":"2；1","analysis":"由逐差 x_6-x_3 = 3aT^2，6=3a，a=2 m/s^2。第3 s内位移等于第2.5 s末速度乘1 s，即 v_2.5 = 6 m/s，v_0 = v_2.5 - a×2.5 = 6-5 = 1 m/s。"},
{"qtype":"填空题","difficulty":2,"stem":"汽车以 15 m/s 匀速行驶，刹车后做匀减速，加速度大小为 3 m/s^2，则刹车后 6 s 内汽车的位移为____ m。","options":[],"answer":"37.5","analysis":"停车时间 t_0 = 15/3 = 5 s < 6 s，故 6 s 内位移即刹车距离 x = v_0^2/(2a) = 225/6 = 37.5 m。易错点是直接代入 t=6 s 得 54 m，那是错误的。"},
{"qtype":"填空题","difficulty":3,"stem":"从同一高度先后释放两个小球，相隔 2 s（g 取 10 m/s^2，不计空气阻力），在第一个球释放后____ s，两球之间的距离为 25 m。","options":[],"answer":"2.25","analysis":"距离差 = ½g[t^2-(t-2)^2] = 5(4t-4) = 20t-20 = 25，解得 t = 2.25 s。注意必须 t>2 s 第二球已释放。"},
{"qtype":"解答题","difficulty":2,"stem":"一辆汽车从静止出发做匀加速直线运动，加速度为 2 m/s^2，求：(1) 5 s 末的速度；(2) 前 5 s 内的位移；(3) 第 5 s 内的位移。","options":[],"answer":"(1) v = at = 2×5 = 10 m/s。(2) x = ½at^2 = 0.5×2×25 = 25 m。(3) 第5 s内位移等于前5 s位移减去前4 s位移：前4 s x_4 = 0.5×2×16 = 16 m，故第5 s内 Δx = 25-16 = 9 m。","analysis":"区分「前5 s」与「第5 s内」。第5 s内指 t=4 s 到 t=5 s 这一秒，用两段位移相减最稳妥。"},
{"qtype":"解答题","difficulty":3,"stem":"列车以 72 km/h 的速度在平直轨道上匀速行驶，因调度需要在某小站临时停车 1 min，刹车加速度大小为 0.5 m/s^2，启动后加速度大小为 1 m/s^2，最终恢复原速。求因停车共耽误多少时间。","options":[],"answer":"先统一单位 v_0 = 72 km/h = 20 m/s。刹车时间 t_1 = v_0/a_1 = 20/0.5 = 40 s，刹车距离 x_1 = v_0^2/(2a_1) = 400/1 = 400 m。启动时间 t_2 = v_0/a_2 = 20/1 = 20 s，启动距离 x_2 = v_0^2/(2a_2) = 400/2 = 200 m。若不停车，经过这两段距离用时 t_原 = (x_1+x_2)/v_0 = 600/20 = 30 s。实际用时 = t_1+t_2+t_停 = 40+20+60 = 120 s。耽误时间 = 120-30 = 90 s。","analysis":"「耽误时间」不是简单加停车时间，而要用实际总时间减去若匀速通过这些距离的时间。这是刹车+启动类问题的标准解法。"},
{"qtype":"解答题","difficulty":3,"stem":"一枚火箭从地面竖直向上发射，加速度恒为 20 m/s^2，经过 5 s 燃料烧尽（此时仍有向上速度），此后只受重力（g 取 10 m/s^2）。求：(1) 燃料烧尽时火箭的高度和速度；(2) 火箭上升的最大高度；(3) 火箭从发射到落回地面总时间。","options":[],"answer":"(1) 加速上升阶段：v_1 = at = 20×5 = 100 m/s，h_1 = ½at^2 = 0.5×20×25 = 250 m。(2) 燃料烧尽后做竖直上抛，继续上升时间 t_2 = v_1/g = 100/10 = 10 s，继续上升高度 h_2 = v_1^2/(2g) = 10000/20 = 500 m。最大高度 H = 250+500 = 750 m。(3) 从最高点自由下落 H=750 m，用时 t_3 = √(2H/g) = √(1500/10)=√150 ≈ 12.25 s。总时间 = 5+10+12.25 ≈ 27.25 s。","analysis":"分阶段处理：动力段匀加速、无动力段竖直上抛、下落段自由落体。注意燃料烧尽后加速度突变为重力加速度，速度不为零仍继续上升。"}
],
"phy_force": [
{"qtype":"选择题","difficulty":1,"stem":"关于重力，下列说法正确的是","options":["A. 重力的方向总是垂直于接触面","B. 重力的大小与物体的质量成正比，方向竖直向下","C. 物体只有静止时才受重力","D. 重心一定在物体上"],"answer":"B","analysis":"重力方向竖直向下而非垂直接触面；任何状态都受重力；重心不一定在物体上（如圆环）。"},
{"qtype":"选择题","difficulty":1,"stem":"关于弹力，下列说法正确的是","options":["A. 只要两物体接触就一定有弹力","B. 弹力的方向总是垂直于接触面并指向受力物体","C. 弹簧的弹力大小与弹簧长度成正比","D. 绳的拉力方向一定沿绳指向绳收缩方向"],"answer":"D","analysis":"接触还要发生弹性形变才有弹力；压力支持力方向应说垂直接触面指向被支持/被压物体，B表述不严谨；弹簧弹力与形变量（伸长或压缩量）成正比而非原长；绳拉力沿绳收缩方向，D正确。"},
{"qtype":"选择题","difficulty":2,"stem":"关于摩擦力，下列说法正确的是","options":["A. 滑动摩擦力方向一定与物体运动方向相反","B. 静摩擦力的大小可以用 f = μN 计算","C. 滑动摩擦力的大小与接触面积无关","D. 运动的物体一定受滑动摩擦力"],"answer":"C","analysis":"滑动摩擦力方向与相对运动方向相反，可与运动方向相同（如传送带加速）；f=μN 只用于滑动摩擦；滑动摩擦与接触面积、速度无关；运动物体间若无相对运动或光滑就没有滑动摩擦。C正确。"},
{"qtype":"选择题","difficulty":2,"stem":"用水平力 F 把一个木块压在竖直墙上保持静止，逐渐增大 F，则","options":["A. 木块受到的摩擦力增大","B. 木块受到的摩擦力减小","C. 木块受到的摩擦力不变，等于重力","D. 木块受到的摩擦力先增大后减小"],"answer":"C","analysis":"木块静止，竖直方向二力平衡：静摩擦力等于重力，与水平压力无关。增大 F 只是增大最大静摩擦力，实际摩擦力仍等于重力。这是经典易错点。"},
{"qtype":"选择题","difficulty":2,"stem":"一个物体放在倾角为 θ 的斜面上恰好匀速下滑，则物体与斜面间的动摩擦因数为","options":["A. sinθ","B. cosθ","C. tanθ","D. cotθ"],"answer":"C","analysis":"匀速下滑时沿斜面方向 mgsinθ = μmgcosθ，解得 μ = tanθ。"},
{"qtype":"选择题","difficulty":3,"stem":"质量为 m 的木块放在倾角 θ 的斜面上，木块与斜面间动摩擦因数为 μ（μ < tanθ），为使木块静止，沿斜面向上施加的最小力为","options":["A. mgsinθ - μmgcosθ","B. mgsinθ + μmgcosθ","C. mgsinθ","D. μmgcosθ"],"answer":"A","analysis":"μ<tanθ 说明不加力物块会下滑。要使物块恰好不下滑（即将下滑），静摩擦沿斜面向上达到最大，沿斜面方向 F + μmgcosθ = mgsinθ，F_min = mgsinθ - μmgcosθ。若求不向上滑动的最大力则为 mgsinθ+μmgcosθ。"},
{"qtype":"选择题","difficulty":3,"stem":"三个共点力大小分别为 3 N、4 N、5 N，方向在平面内可任意调整，则它们的合力大小可能是","options":["A. 0","B. 12 N","C. 13 N","D. 14 N"],"answer":"A","analysis":"三个力中最大力 5 N ≤ 另两力之和 7 N，故可平衡，合力可为零。三力同向最大合力 12 N，故合力范围 0~12 N。选项中 0 是可能值。"},
{"qtype":"选择题","difficulty":3,"stem":"用轻绳 AO、BO 悬挂一重物，AO 水平，BO 与竖直方向成 30°角，重物重力为 G，则 BO 绳的拉力大小为","options":["A. G","B. √3 G","C. 2G","D. 2G/√3"],"answer":"D","analysis":"对结点受力分析：BO 拉力 T_B 沿 BO，AO 拉力 T_A 水平。竖直方向 T_B cos30° = G，故 T_B = G/cos30° = 2G/√3。水平方向 T_A = T_B sin30° = G/√3。"},
{"qtype":"填空题","difficulty":1,"stem":"质量为 5 kg 的物体放在水平地面上，物体与地面间动摩擦因数为 0.2，用水平力 15 N 拉物体（g 取 10 m/s^2），物体受到的滑动摩擦力为____ N。","options":[],"answer":"10","analysis":"滑动摩擦力 f = μN = μmg = 0.2×5×10 = 10 N，与水平拉力大小无关（只要发生相对滑动）。"},
{"qtype":"填空题","difficulty":2,"stem":"一根轻弹簧原长 10 cm，挂 2 N 物体时长度为 12 cm，若挂 5 N 物体（仍在弹性限度内），弹簧长度为____ cm。","options":[],"answer":"15","analysis":"由胡克定律 F = kΔx。挂2 N时伸长 2 cm，k = 2/2 = 1 N/cm。挂5 N时伸长 5 cm，总长 = 10+5 = 15 cm。"},
{"qtype":"填空题","difficulty":2,"stem":"两个共点力 F_1 = 6 N、F_2 = 8 N，相互垂直，则它们的合力大小为____ N；当两力夹角为 180°时合力为____ N。","options":[],"answer":"10；2","analysis":"垂直时合力 F = √(6^2+8^2) = 10 N。反向时合力 = 8-6 = 2 N（方向沿 8 N 的力）。"},
{"qtype":"填空题","difficulty":3,"stem":"质量为 m 的物体静止在倾角为 θ 的斜面上，则斜面对物体的支持力大小为____，物体受到的静摩擦力大小为____。","options":[],"answer":"mgcosθ；mgsinθ","analysis":"垂直斜面方向 N = mgcosθ；沿斜面方向静摩擦 f = mgsinθ 平衡重力分力。"},
{"qtype":"解答题","difficulty":2,"stem":"质量 m = 2 kg 的物块放在水平桌面上，物块与桌面间动摩擦因数 μ = 0.2。现用与水平方向成 37°斜向上的拉力 F = 10 N 拉物块（g 取 10 m/s^2，sin37°=0.6，cos37°=0.8）。求：(1) 桌面对物块的支持力；(2) 物块受到的摩擦力。","options":[],"answer":"(1) 竖直方向受力平衡：N + Fsin37° = mg，N = 2×10 - 10×0.6 = 20-6 = 14 N。(2) 水平方向拉力分力 Fcos37° = 10×0.8 = 8 N。最大滑动摩擦力 f = μN = 0.2×14 = 2.8 N。因拉力分力 8 N > 2.8 N，物块滑动，摩擦力 = μN = 2.8 N。","analysis":"斜向上拉力会减小正压力，这是关键。先由竖直平衡求 N，再判断能否滑动。注意若拉力分力小于最大静摩擦则为静摩擦且大小等于拉力分力，本题 8 N > 2.8 N 故滑动。"},
{"qtype":"解答题","difficulty":3,"stem":"如图（描述）：用两根等长轻绳将重力为 G 的光滑小球悬挂，两绳与竖直方向夹角均为 θ，求每根绳的拉力大小。若两绳夹角变为 90°（对称，θ=45°），拉力又为多少？","options":[],"answer":"对小球受力分析：重力 G 和两绳拉力 T（对称故相等）。竖直方向 2Tcosθ = G，故 T = G/(2cosθ)。当 θ=45°，cos45°=√2/2，T = G/(2×√2/2) = G/√2 = √2 G/2。","analysis":"利用对称性两绳拉力相等，正交分解后竖直方向平衡。夹角越大（θ越大），cosθ越小，拉力越大——这是分力随夹角增大而增大的结论。"},
{"qtype":"解答题","difficulty":3,"stem":"质量 M = 4 kg 的木板放在光滑水平面上，质量 m = 1 kg 的物块放在木板上，物块与木板间动摩擦因数 μ = 0.4。现用水平力 F = 10 N 拉物块（g 取 10 m/s^2），判断物块与木板间是否发生相对滑动，并求两者加速度。","options":[],"answer":"物块与木板间最大静摩擦（近似滑动摩擦）f_max = μmg = 0.4×1×10 = 4 N。假设两者一起运动，则共同加速度 a = F/(M+m) = 10/5 = 2 m/s^2。此时木板所需静摩擦力 f = Ma = 4×2 = 8 N > f_max = 4 N，假设不成立，两者发生相对滑动。滑动后物块受摩擦力 4 N，a_m = (F-f)/m = (10-4)/1 = 6 m/s^2；木板受摩擦力 4 N，a_M = f/M = 4/4 = 1 m/s^2。","analysis":"板块问题先用「假设法」：假设共速求所需静摩擦，与最大静摩擦比较。超过则滑动，分别用各自受力求加速度。"}
]
})

BANK.update({
"phy_newton2": [
{"qtype":"选择题","difficulty":1,"stem":"关于牛顿第一定律，下列说法正确的是","options":["A. 物体只有在静止时才有惯性","B. 力是维持物体运动的原因","C. 力是改变物体运动状态的原因","D. 速度大的物体惯性大"],"answer":"C","analysis":"惯性是物体固有属性，质量是唯一量度，与运动状态无关；力不是维持运动的原因而是改变运动状态（产生加速度）的原因。"},
{"qtype":"选择题","difficulty":1,"stem":"根据牛顿第二定律，下列说法正确的是","options":["A. 物体所受合外力为零时，速度一定为零","B. 物体所受合外力越大，速度越大","C. 物体加速度方向与所受合外力方向相同","D. 同一物体质量不变，加速度与合外力成反比"],"answer":"C","analysis":"合外力为零时加速度为零，速度不变（可匀速）；合外力决定加速度而非速度；a 与 F 成正比、与 m 成反比；加速度方向与合外力方向相同。"},
{"qtype":"选择题","difficulty":2,"stem":"质量为 2 kg 的物体在水平面上受水平拉力 10 N，物体与地面间动摩擦因数 0.2（g=10），则物体的加速度为","options":["A. 3 m/s^2","B. 5 m/s^2","C. 7 m/s^2","D. 0"],"answer":"A","analysis":"摩擦力 f = μmg = 0.2×2×10 = 4 N。合外力 F_合 = 10-4 = 6 N，a = F_合/m = 6/2 = 3 m/s^2。"},
{"qtype":"选择题","difficulty":2,"stem":"电梯中一人站在体重计上，电梯运动时体重计示数小于人的实际重力，则电梯可能的运动是","options":["A. 匀速上升","B. 加速上升","C. 减速上升","D. 减速下降"],"answer":"C","analysis":"示数小于重力为失重，加速度方向向下。加速上升和减速下降加速度向上为超重；减速上升加速度向下为失重。"},
{"qtype":"选择题","difficulty":2,"stem":"关于作用力与反作用力，下列说法正确的是","options":["A. 作用力与反作用力可以平衡","B. 作用力与反作用力作用在同一物体上","C. 作用力与反作用力大小相等方向相反，作用在两个物体上","D. 先有作用力后有反作用力"],"answer":"C","analysis":"作用力反作用力作用在两个不同物体上，不能平衡，同时产生同时消失。平衡力才作用在同一物体上。"},
{"qtype":"选择题","difficulty":3,"stem":"质量为 m 的物体沿倾角 θ 的光滑斜面下滑，其加速度为","options":["A. g","B. gsinθ","C. gcosθ","D. gtanθ"],"answer":"B","analysis":"光滑斜面无摩擦，沿斜面合力 = mgsinθ，故 a = gsinθ。垂直斜面方向 N = mgcosθ 平衡。"},
{"qtype":"选择题","difficulty":3,"stem":"质量分别为 m_1 和 m_2 的两物块用轻绳连接放在光滑水平面上，用水平力 F 拉 m_1，则绳的拉力为","options":["A. F","B. m_1 F/(m_1+m_2)","C. m_2 F/(m_1+m_2)","D. 0"],"answer":"C","analysis":"整体加速度 a = F/(m_1+m_2)。对 m_2 单独分析，绳拉力提供其加速度：T = m_2 a = m_2 F/(m_1+m_2)。这是连接体问题的隔离法。"},
{"qtype":"选择题","difficulty":3,"stem":"竖直向上抛出一个物体，若不计空气阻力，在上升和下降过程中（同一高度处），下列说法正确的是","options":["A. 上升时加速度大于下降时","B. 上升和下降加速度相同，均为 g 向下","C. 上升时速度方向与加速度方向相同","D. 最高点速度为零加速度也为零"],"answer":"B","analysis":"不计阻力，整个过程只受重力，加速度恒为 g 竖直向下。上升阶段速度向上与加速度反向故减速；最高点速度为零但加速度仍为 g。"},
{"qtype":"填空题","difficulty":1,"stem":"质量为 4 kg 的物体受到两个互相垂直的水平力 3 N 和 4 N 作用，则物体的加速度大小为____ m/s^2。","options":[],"answer":"1.25","analysis":"两力垂直，合力 F = √(3^2+4^2) = 5 N，a = F/m = 5/4 = 1.25 m/s^2。"},
{"qtype":"填空题","difficulty":2,"stem":"质量为 60 kg 的人站在电梯内的体重计上，电梯以 2 m/s^2 的加速度匀加速上升（g=10），体重计的示数为____ N。","options":[],"answer":"720","analysis":"加速上升超重，支持力 N - mg = ma，N = m(g+a) = 60×12 = 720 N。示数等于支持力大小。"},
{"qtype":"填空题","difficulty":2,"stem":"质量为 1 kg 的物体静止在光滑水平面上，受水平力 F 作用，前 2 s 内 F=4 N，则 2 s 末物体速度为____ m/s，2 s 内位移为____ m。","options":[],"answer":"8；8","analysis":"a = F/m = 4 m/s^2。v = at = 4×2 = 8 m/s；x = ½at^2 = 0.5×4×4 = 8 m。"},
{"qtype":"填空题","difficulty":3,"stem":"质量为 2 kg 的物体在水平面上，受与水平方向成 37°角斜向上的拉力 10 N，物体与地面间动摩擦因数 0.5（g=10，sin37°=0.6，cos37°=0.8），物体的加速度为____ m/s^2。","options":[],"answer":"0.5","analysis":"竖直方向 N = mg - Fsin37° = 20-6 = 14 N。摩擦力 f = μN = 0.5×14 = 7 N。水平合力 = Fcos37° - f = 8-7 = 1 N。a = 1/2 = 0.5 m/s^2。"},
{"qtype":"解答题","difficulty":2,"stem":"质量 m = 5 kg 的物体放在光滑水平面上，受水平拉力 F = 20 N 作用。求：(1) 加速度；(2) 由静止开始 3 s 末的速度；(3) 前 3 s 的位移。","options":[],"answer":"(1) a = F/m = 20/5 = 4 m/s^2。(2) v = at = 4×3 = 12 m/s。(3) x = ½at^2 = 0.5×4×9 = 18 m。","analysis":"光滑水平面无摩擦，合外力即拉力。直接用牛顿第二定律与运动学公式联立。"},
{"qtype":"解答题","difficulty":3,"stem":"质量 m = 2 kg 的物块以初速度 v_0 = 6 m/s 沿粗糙水平面滑行，物块与地面间动摩擦因数 μ = 0.3（g=10）。求：(1) 滑行时的加速度大小；(2) 物块停下来所需时间；(3) 滑行总距离。","options":[],"answer":"(1) 滑行时水平方向只受摩擦力 f = μmg = 0.3×2×10 = 6 N，方向与运动相反，a = f/m = μg = 3 m/s^2（减速，大小 3 m/s^2）。(2) 停下时 v=0，由 v = v_0 - at 得 t = v_0/a = 6/3 = 2 s。(3) 总距离 x = v_0^2/(2a) = 36/6 = 6 m（或 x = v_0 t - ½at^2 = 12-6 = 6 m）。","analysis":"滑行问题中摩擦力提供减速加速度，a = μg 与质量无关。注意先判断末速度为零的时间。"},
{"qtype":"解答题","difficulty":3,"stem":"质量 M = 3 kg 的木板静止在光滑水平面上，质量 m = 1 kg 的小物块放在木板左端，物块与木板间动摩擦因数 μ = 0.2（g=10）。现用水平恒力 F = 6 N 拉物块。求物块和木板的加速度（假设两者发生相对滑动）。","options":[],"answer":"物块与木板间摩擦力 f = μmg = 0.2×1×10 = 2 N。对物块：水平方向 F - f = ma_m，a_m = (6-2)/1 = 4 m/s^2。对木板：水平方向只受摩擦力 f，a_M = f/M = 2/3 ≈ 0.67 m/s^2。验证：若一起运动需静摩擦 f' = Ma = M·F/(M+m) = 3×6/4 = 4.5 N > 最大静摩擦 2 N，确实相对滑动。","analysis":"板块问题先判断是否相对滑动，再分别隔离求加速度。注意物块受向左摩擦，木板受向右摩擦。"}
],
"phy_curve": [
{"qtype":"选择题","difficulty":1,"stem":"关于曲线运动，下列说法正确的是","options":["A. 曲线运动速度方向一定变化，是变速运动","B. 曲线运动加速度一定变化","C. 曲线运动速度大小一定变化","D. 两个直线运动的合运动一定是直线运动"],"answer":"A","analysis":"曲线运动速度方向沿切线时刻改变，故一定是变速运动；加速度可以恒定（平抛）；速度大小可以不变（匀速圆周）；两个直线运动合成可能是曲线（如平抛）。"},
{"qtype":"选择题","difficulty":1,"stem":"做曲线运动的物体，其所受合外力方向与速度方向的关系是","options":["A. 一定在同一直线上","B. 一定不在同一直线上","C. 可以垂直也可以共线","D. 无法确定"],"answer":"B","analysis":"物体做曲线运动的条件就是合外力（加速度）方向与速度方向不在同一直线上。"},
{"qtype":"选择题","difficulty":2,"stem":"关于平抛运动，下列说法正确的是","options":["A. 平抛运动是非匀变速运动","B. 平抛运动落地时间与初速度有关","C. 平抛运动水平位移由初速度和高度共同决定","D. 平抛运动在相等时间内速度变化量不相等"],"answer":"C","analysis":"平抛只受重力，是匀变速运动，加速度恒为 g；落地时间只由高度决定 t=√(2h/g)；水平位移 x = v_0 t 由 v_0 和 h 共同决定；相等时间内 Δv = gΔt 相等。"},
{"qtype":"选择题","difficulty":2,"stem":"从同一高度以不同初速度水平抛出两个小球（不计空气阻力），它们落地的先后顺序是","options":["A. 初速度大的先落地","B. 初速度小的先落地","C. 同时落地","D. 无法判断"],"answer":"C","analysis":"平抛落地时间由竖直方向自由落体决定，t = √(2h/g)，与水平初速度无关。高度相同则同时落地。"},
{"qtype":"选择题","difficulty":2,"stem":"关于匀速圆周运动，下列说法正确的是","options":["A. 匀速圆周运动是匀速运动","B. 匀速圆周运动线速度不变","C. 匀速圆周运动角速度不变","D. 匀速圆周运动加速度为零"],"answer":"C","analysis":"匀速圆周运动线速度方向时刻改变，是变速运动；角速度大小方向（按高中理解）不变；向心加速度不为零。"},
{"qtype":"选择题","difficulty":3,"stem":"做匀速圆周运动的物体，轨道半径为 r，线速度为 v，则下列关系正确的是","options":["A. 向心加速度 a = v/r","B. 向心加速度 a = v^2/r","C. 角速度 ω = v/r^2","D. 周期 T = 2πv"],"answer":"B","analysis":"向心加速度 a = v^2/r = ω^2 r；ω = v/r；周期 T = 2π/ω = 2πr/v。"},
{"qtype":"选择题","difficulty":3,"stem":"汽车在水平圆弧弯道上以恒定速率行驶，弯道半径为 R，轮胎与路面间动摩擦因数为 μ，为使汽车不侧滑，车速最大不超过","options":["A. √(μgR)","B. √(gR/μ)","C. μgR","D. √(2μgR)"],"answer":"A","analysis":"水平弯道由静摩擦提供向心力，最大速度对应最大静摩擦 μmg = mv^2/R，解得 v = √(μgR)。"},
{"qtype":"选择题","difficulty":3,"stem":"一小球做平抛运动，落地时速度方向与水平方向成 45°角，已知初速度为 10 m/s（g=10），则抛出点高度为","options":["A. 5 m","B. 10 m","C. 15 m","D. 20 m"],"answer":"A","analysis":"落地速度方向与水平成45°，即 tan45° = v_y/v_0 = 1，故 v_y = v_0 = 10 m/s。由 v_y = gt 得 t = 1 s，高度 h = ½gt^2 = 5 m。"},
{"qtype":"填空题","difficulty":1,"stem":"做匀速圆周运动的物体，半径 r = 2 m，周期 T = 2 s，则线速度 v = ____ m/s，角速度 ω = ____ rad/s。","options":[],"answer":"2π；π","analysis":"v = 2πr/T = 4π/2 = 2π m/s；ω = 2π/T = π rad/s。"},
{"qtype":"填空题","difficulty":2,"stem":"从 h = 20 m 高处以 v_0 = 10 m/s 水平抛出一小球（g=10），小球落地时间为____ s，水平射程为____ m。","options":[],"answer":"2；20","analysis":"竖直方向 h = ½gt^2，t = √(2×20/10) = 2 s。水平射程 x = v_0 t = 10×2 = 20 m。"},
{"qtype":"填空题","difficulty":2,"stem":"质量为 0.5 kg 的物体做匀速圆周运动，半径 0.4 m，线速度 2 m/s，则向心加速度大小为____ m/s^2，所需向心力为____ N。","options":[],"answer":"10；5","analysis":"a = v^2/r = 4/0.4 = 10 m/s^2；F = ma = 0.5×10 = 5 N。"},
{"qtype":"填空题","difficulty":3,"stem":"平抛运动中，某时刻物体速度方向与水平方向夹角为 30°，初速度 v_0 = 20 m/s（g=10），则该时刻已飞行时间为____ s。","options":[],"answer":"2√3/3","analysis":"tan30° = v_y/v_0 = gt/v_0，t = v_0 tan30°/g = 20×(1/√3)/10 = 2/√3 = 2√3/3 s。"},
{"qtype":"解答题","difficulty":2,"stem":"从 1.25 m 高的桌面上，以 2 m/s 的初速度水平弹出一个小球（g=10）。求：(1) 小球落地时间；(2) 水平射程；(3) 落地时竖直分速度大小。","options":[],"answer":"(1) 竖直方向 h = ½gt^2，t = √(2h/g) = √(2×1.25/10) = √0.25 = 0.5 s。(2) 水平射程 x = v_0 t = 2×0.5 = 1 m。(3) 竖直分速度 v_y = gt = 10×0.5 = 5 m/s。","analysis":"平抛运动分解为水平匀速和竖直自由落体，分别用各自公式。"},
{"qtype":"解答题","difficulty":3,"stem":"长 L = 0.5 m 的轻绳一端固定，另一端系质量 m = 0.2 kg 的小球，使之在竖直面内做圆周运动（g=10）。求小球通过最高点时，绳的拉力恰好为零的临界速度。若通过最高点速度为 4 m/s，绳的拉力为多少？","options":[],"answer":"(1) 最高点临界：绳拉力为零，重力恰好提供向心力，mg = mv^2/L，v = √(gL) = √(10×0.5) = √5 ≈ 2.24 m/s。(2) 最高点 v = 4 m/s 时，向心力由重力和绳拉力共同提供：T + mg = mv^2/L，T = mv^2/L - mg = 0.2×16/0.5 - 0.2×10 = 6.4 - 2 = 4.4 N。","analysis":"竖直圆周最高点：合力指向圆心（向下），即 T + mg = mv^2/L。临界条件 T=0。注意绳模型只能拉不能推。"},
{"qtype":"解答题","difficulty":3,"stem":"飞机在离地面 h = 500 m 的高空以 v_0 = 100 m/s 的水平速度飞行（g=10）。为使投下的炸弹命中地面目标，求：(1) 炸弹落地时间；(2) 飞机应在离目标水平距离多远处投弹。","options":[],"answer":"(1) 炸弹做平抛运动，竖直方向 h = ½gt^2，t = √(2h/g) = √(2×500/10) = √100 = 10 s。(2) 水平方向炸弹保持飞机速度匀速运动，水平距离 x = v_0 t = 100×10 = 1000 m。即飞机应在离目标水平距离 1000 m 处投弹。","analysis":"投弹问题本质是平抛。炸弹离开飞机后水平速度不变，竖直自由下落。"}
]
})

